// Generated by `npm run test:generate`. Re-running overwrites this file.
import { test } from '@playwright/test';
import { editCombinedExcelFile, executePayrollUpload, navigateToPayroll, navigateToPayrollManagePage, verifyErrorCount } from '../steps/payroll-steps';

test.describe("Payroll duplicate rows", () => {
  test("Duplicate rows raise an error on the ECR page", async ({ page }) => {
    await test.step("Given Navigate to Payroll", async () => {
      await navigateToPayroll(page);
    });
    await test.step("And Navigate to payroll manage page for file upload", async () => {
      await navigateToPayrollManagePage(page);
    });
    await test.step("When Edit the Combined Excel file for Duplicate rows with the following details", async () => {
      await editCombinedExcelFile(page, [{"Row":"1","Field":"HIRE DATE","Value":"1/1/2025"},{"Row":"1","Field":"PAY DATE","Value":"2/2/2025"},{"Row":"1","Field":"HOURS","Value":"510"},{"Row":"1","Field":"EEPRETAX","Value":"500"},{"Row":"2","Field":"HIRE DATE","Value":"1/1/2025"},{"Row":"2","Field":"PAY DATE","Value":"2/2/2025"},{"Row":"2","Field":"HOURS","Value":"500"},{"Row":"2","Field":"EEPRETAX","Value":"300"}]);
    });
    await test.step("And Payroll file is executed to upload", async () => {
      await executePayrollUpload(page);
    });
    await test.step("Then Verify The Error Count On Ecr Page", async () => {
      await verifyErrorCount(page, [{"Warning Count":"2","Error Count":"1"}]);
    });
  });
});
